<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {get,post,api} from '../api'
import {questions} from '../intelligence'
import EventDetail from '../components/EventDetail.vue'
import ReportPreview from '../components/ReportPreview.vue'
import ResearchRun from '../components/ResearchRun.vue'
const loading=ref(false),failed=ref(false),companies=ref<any[]>([]),technologies=ref<string[]>([]),weekly=ref<any[]>([]),personal=ref<any[]>([]),follows=ref<any[]>([]),runs=ref<any[]>([]),reports=ref<any[]>([])
const query=ref(''),days=ref(30),companyId=ref<number|null>(null),technology=ref<string|null>(null),researchId=ref<number|null>(null),eventId=ref<number|null>(null),digest=ref<any>(null),followCompany=ref<number|null>(null),followTechnology=ref(''),weekDays=ref(7)
async function load(){loading.value=true;failed.value=false;try{[companies.value,technologies.value,follows.value,runs.value,reports.value]=await Promise.all(['/companies?limit=200','/workspace/technologies','/workspace/follows','/workspace/research','/reports'].map(get));weekly.value=(await get('/workspace/events?days='+weekDays.value+'&limit=8')).items;personal.value=(await get('/workspace/events?days=30&followed=true&limit=8')).items}catch{failed.value=true}finally{loading.value=false}}
async function research(text=query.value){if(!text.trim())return;const run=await post('/workspace/research',{query:text,days:days.value,company_id:companyId.value,technology:technology.value,allow_search:true});researchId.value=run.id;await load()}
async function follow(type:string,key:string){await post('/workspace/follows',{target_type:type,target_key:key});await load()}
async function unfollow(id:number){await api.delete('/workspace/follows/'+id);await load()}
const names=(id:number|string)=>companies.value.find(c=>c.id===Number(id))?.name||id
const reviewLabel=(e:any)=>e.review_status==='reviewed'?'已审阅':e.review_status==='questionable'?'存疑':'待核实'
onMounted(load)
</script>
<template><div v-loading="loading"><div class="page-heading"><div><div class="eyebrow">FIND WHAT MATTERS · VERIFY · TRACK</div><h1>今天，你想了解具身智能行业的什么？</h1><p>研究一个问题，追溯一项进展，持续关注你在意的企业。</p></div><el-button @click="load">刷新</el-button></div><el-alert v-if="failed" type="error" title="加载失败，请检查服务后刷新"/>
<section class="panel"><el-input v-model="query" type="textarea" :rows="2" placeholder="例如：最近一个月有哪些企业在 VLA 方向取得进展？"/><div class="toolbar" style="margin-top:16px"><el-select v-model="days" style="width:140px"><el-option label="最近7天" :value="7"/><el-option label="最近30天" :value="30"/><el-option label="最近90天" :value="90"/></el-select><el-select v-model="companyId" clearable filterable placeholder="企业范围" style="width:220px"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="technology" clearable placeholder="技术范围" style="width:220px"><el-option v-for="t in technologies" :key="t" :label="t" :value="t"/></el-select><el-button type="primary" @click="research()">开始真实研究</el-button></div><p>优先查询已有证据；资料不足时最多一次公开搜索与三篇正文补充。复杂财务预测或无公开资料的问题无法保证回答。</p></section>
<h2>推荐研究问题</h2><p>人工设计的问题模板，不是实时热搜排名；沿用上方时间、企业与技术范围。</p><div class="question-grid"><button class="question-card" v-for="(q,i) in questions" :key="q.id" @click="query=q.title;research(q.title)"><span class="eyebrow">0{{i+1}} / START RESEARCH</span><h2>{{q.title}}</h2><p>{{q.description}} →</p></button></div><ResearchRun :id="researchId"/>
<section class="panel"><div class="section-heading"><h2>{{weekDays===7?'本周':'最近30天'}}重要进展</h2><el-button @click="weekDays=weekDays===7?30:7;load()">{{weekDays===7?'查看过去30天':'切回本周'}}</el-button></div><article v-for="e in weekly" :key="e.id" class="briefing-event"><div><router-link :to="'/companies/'+e.company_id">{{e.company_name}}</router-link><span>{{e.occurred_at||e.published_at||'时间未知'}}</span></div><h3><el-button link @click="eventId=e.id">{{e.title}}</el-button></h3><p>{{e.directions.join(' / ')}} · {{e.event_type}} · {{e.progress_stage}}</p><p>来源：{{e.source_domains?.join(' / ')}}</p><p>重要性 {{e.importance}} · {{e.evidence_levels.join(' / ')}} · {{reviewLabel(e)}} · {{e.member_ids.length}} 条关联报道</p><el-button link @click="eventId=e.id">来源、声明与不确定性 ↗</el-button></article><el-empty v-if="!weekly.length" description="没有符合当前时间范围的公开事件；未知时间与旧闻不会作为本周新闻。"/></section>
<section class="panel"><h2>我的关注</h2><div class="toolbar"><el-select data-testid="follow-company" v-model="followCompany" filterable clearable placeholder="关注企业" style="width:220px"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button :disabled="!followCompany" @click="follow('company',String(followCompany))">关注企业</el-button><el-select v-model="followTechnology" clearable placeholder="关注技术" style="width:220px"><el-option v-for="t in technologies" :key="t" :label="t" :value="t"/></el-select><el-button :disabled="!followTechnology" @click="follow('technology',followTechnology)">关注方向</el-button><el-button @click="post('/workspace/digest?days=7&followed=true').then(r=>{digest=r;load()})">生成关注周报</el-button><router-link to="/following">完整关注情报流 →</router-link></div><div class="toolbar"><el-tag v-for="f in follows" :key="f.id" closable @close="unfollow(f.id)">{{f.target_type==='company'?names(f.target_key):f.target_key}}</el-tag></div><div v-for="e in personal" :key="e.id" class="claim"><el-button link @click="eventId=e.id">{{e.company_name}} · {{e.title}}</el-button><p>{{e.occurred_at||e.published_at}} · {{e.evidence_levels.join(' / ')}} · 重要性 {{e.importance}}</p></div><el-empty v-if="!personal.length" description="最近30天暂无匹配的关注进展；可以先添加关注对象。"/></section>
<section class="panel"><h2>最近研究与报告</h2><p v-for="r in runs.slice(0,5)" :key="r.id"><el-button link @click="researchId=r.id">#{{r.id}} {{r.user_query}} · {{r.status}}</el-button></p><p v-for="r in reports.slice(0,5)" :key="'r'+r.id"><el-button link @click="digest=r">{{r.title}} · {{r.created_at}}</el-button></p><el-empty v-if="!runs.length&&!reports.length" description="尚无研究任务或报告"/></section>
<EventDetail :id="eventId" @close="eventId=null"/><el-dialog :model-value="!!digest" @close="digest=null" title="研究简报" width="min(900px,95vw)"><ReportPreview v-if="digest" :report="digest"/></el-dialog></div></template>
